var fx=UnityEngine.Object.FindAnyObjectByType<NeoReactiveTiles>();var b=fx.board;var actor=UnityEngine.Object.FindAnyObjectByType<NeoGridMotor>();var controller=UnityEngine.Object.FindAnyObjectByType<Controller>();
if(!UnityEditor.EditorApplication.isPlaying||!b.Ready||DemoBootstrap.IsPaused)throw new System.Exception("Expected active exploration");
var oldRadius=fx.visibleRadius;var start=actor.transform.position;bool control=controller.enabled;controller.enabled=false;fx.enabled=false;
var maps=b.GetComponentsInChildren<UnityEngine.Tilemaps.Tilemap>().Where(m=>m!=b.walls&&m.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>()==null).ToArray();
var samples=new System.Collections.Generic.List<(NeoReactiveTiles.Surface surface,UnityEngine.Tilemaps.Tilemap map,UnityEngine.Vector3Int cell,UnityEngine.Matrix4x4 matrix,UnityEngine.Color color,UnityEngine.Tilemaps.TileFlags flags)>();
foreach(var style in fx.styles){bool found=false;foreach(var map in maps){foreach(var cell in map.cellBounds.allPositionsWithin){if(!style.tiles.Contains(map.GetTile(cell)))continue;samples.Add((style.surface,map,cell,map.GetTransformMatrix(cell),map.GetColor(cell),map.GetTileFlags(cell)));found=true;break;}if(found)break;}if(!found)throw new System.Exception("Missing surface "+style.surface);}
int blocks=b.walls.GetUsedTilesCount();var checks=new System.Collections.Generic.List<string>();fx.visibleRadius=10000;fx.enabled=true;
var initialFrame=UnityEngine.Time.frameCount;int stage=0;double next=UnityEditor.EditorApplication.timeSinceStartup+.4;double deadline=next+15;int initialReactions=fx.ReactionCount;UnityEngine.Vector2Int stepDelta=UnityEngine.Vector2Int.zero;UnityEngine.Vector2Int testTarget=UnityEngine.Vector2Int.zero;bool targetFound=false;var grassStyle=fx.styles.First(s=>s.surface==NeoReactiveTiles.Surface.GroundGrass);foreach(var g in b.floor.cellBounds.allPositionsWithin){var target=new UnityEngine.Vector2Int(g.x,g.y);if(!grassStyle.tiles.Contains(b.floor.GetTile(g))||b.Blocked(target))continue;foreach(var d in new[]{UnityEngine.Vector2Int.up,UnityEngine.Vector2Int.down,UnityEngine.Vector2Int.left,UnityEngine.Vector2Int.right}){if(b.Blocked(target-d))continue;testTarget=target;stepDelta=d;targetFound=true;break;}if(targetFound)break;}if(!targetFound)throw new System.Exception("No walkable grass test cell");
UnityEditor.EditorApplication.CallbackFunction tick=null;
void Cleanup(){UnityEditor.EditorApplication.update-=tick;actor.Teleport(start);controller.enabled=control;fx.visibleRadius=oldRadius;if(!fx.enabled)fx.enabled=true;}
tick=()=>{try{var now=UnityEditor.EditorApplication.timeSinceStartup;if(now>deadline)throw new System.Exception("Test timeout");if(now<next)return;
if(stage==0){foreach(var s in samples){if(s.surface==NeoReactiveTiles.Surface.Foliage){if(s.map.GetTransformMatrix(s.cell)==s.matrix)throw new System.Exception("Missing foliage idle");}else if(s.map.GetColor(s.cell)!=s.color)throw new System.Exception("Terrain tint changed "+s.surface);}checks.Add("Foliage idle moves while continuous terrain retains its original tint");foreach(var s in samples)fx.ReactAt(s.map.GetCellCenterWorld(s.cell));next=now+.18;stage++;}
else if(stage==1){if(fx.ActiveReactionCount<4)throw new System.Exception("Missing contact reactions");foreach(var s in samples)if(s.map.GetColor(s.cell)!=s.color)throw new System.Exception("Footstep changed terrain tint");foreach(var s in samples){if(s.surface==NeoReactiveTiles.Surface.Foliage&&s.map.GetTransformMatrix(s.cell)==s.matrix)throw new System.Exception("Missing bend");}if(fx.GetComponentsInChildren<UnityEngine.LineRenderer>().Count(r=>r.enabled)<2)throw new System.Exception("Missing water/stone contact rings");checks.Add("Idle and contact effects coexist; ripple renderers active");foreach(var s in samples)fx.ReactAt(s.map.GetCellCenterWorld(s.cell));next=now+.18;stage++;}
else if(stage==2){if(fx.ActiveReactionCount<4)throw new System.Exception("Retrigger failed");checks.Add("Repeated footsteps restart cell reactions");next=now+1.1;stage++;}
else if(stage==3){if(fx.ActiveReactionCount!=0)throw new System.Exception("Reactions did not finish");checks.Add("One-shot reactions expire back to idle");fx.enabled=false;foreach(var s in samples)if(s.map.GetTransformMatrix(s.cell)!=s.matrix||s.map.GetColor(s.cell)!=s.color||s.map.GetTileFlags(s.cell)!=s.flags)throw new System.Exception("Restore failed "+s.surface);checks.Add("Disable restores original matrices, colors and flags");fx.enabled=true;initialReactions=fx.ReactionCount;actor.Teleport(NeoGridBoard.Center(testTarget-stepDelta));next=now+.15;stage++;}
else if(stage==4){if(!actor.Step(stepDelta))throw new System.Exception("Movement rejected");next=now+.35;stage++;} else if(stage==5){if(actor.IsMoving||actor.Cell!=testTarget)throw new System.Exception("Movement did not complete");if(fx.ReactionCount<=initialReactions)throw new System.Exception("Motor did not trigger reactions");checks.Add("Actual motor arrival triggers painted cells");if(b.walls.GetUsedTilesCount()!=blocks)throw new System.Exception("Collisions changed");checks.Add("Collision tile assets unchanged");if(UnityEngine.Time.frameCount<=initialFrame)throw new System.Exception("Game frozen");Cleanup();System.IO.File.WriteAllText("docs/design/reactive-tiles-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=true,scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,cells=fx.ReactiveCellCount,checks},Newtonsoft.Json.Formatting.Indented));}
}catch(System.Exception e){Cleanup();System.IO.File.WriteAllText("docs/design/reactive-tiles-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=false,error=e.ToString(),checks},Newtonsoft.Json.Formatting.Indented));}};
UnityEditor.EditorApplication.update+=tick;return new{started=true,surfaces=samples.Select(s=>s.surface.ToString()).ToArray()};